// Generic async retry helper.
//
// Options:
//   retries      number of retries AFTER the first attempt (default 3)
//   baseDelayMs  delay before the first retry (default 100)
//   factor       exponential backoff multiplier (default 2)
//   sleep        (ms, signal) => Promise, injectable for tests
//   signal       optional AbortSignal; aborting cancels further attempts
//
// fn receives the zero-based attempt index.

export function defaultSleep(ms, signal) {
  return new Promise((resolve, reject) => {
    const t = setTimeout(resolve, ms);
    signal?.addEventListener('abort', () => {
      clearTimeout(t);
      reject(signal.reason);
    }, { once: true });
  });
}

function throwIfAborted(signal) {
  if (signal?.aborted) throw signal.reason;
}

// Waits for sleep(ms, signal), but rejects immediately with signal.reason
// if the signal aborts, without waiting for the sleep to settle.
function waitWithAbort(sleep, ms, signal) {
  if (!signal) return sleep(ms, signal);
  return new Promise((resolve, reject) => {
    const onAbort = () => reject(signal.reason);
    signal.addEventListener('abort', onAbort, { once: true });
    const done = () => signal.removeEventListener('abort', onAbort);
    Promise.resolve()
      .then(() => sleep(ms, signal))
      .then(
        (v) => { done(); resolve(v); },
        (e) => { done(); reject(e); },
      );
  });
}

export async function retry(fn, opts = {}) {
  const {
    retries = 3,
    baseDelayMs = 100,
    factor = 2,
    sleep = defaultSleep,
    signal,
  } = opts;

  for (let attempt = 0; ; attempt++) {
    throwIfAborted(signal);
    try {
      return await fn(attempt);
    } catch (err) {
      if (signal?.aborted) throw signal.reason;
      // Caller errors (e.g. HTTP 4xx) are not worth retrying.
      if (err && err.retryable === false) throw err;
      // attempt is zero-based: attempts 0..retries means retries + 1 total.
      if (attempt >= retries) throw err;
      // No sleep after the final failed attempt (handled above).
      await waitWithAbort(sleep, baseDelayMs * factor ** attempt, signal);
    }
  }
}

